Rules.InvariantScript:
Table(
    {
        ItemKey: "lang",
        ItemDisplayName: $"Hi {User().FullName}"
    },
    {
        ItemKey: "appSettingsKey",
        ItemDisplayName: $"Application Settings",
        ItemIconName: "Settings",
        ItemVisible: Or(
            gblCurrentUser.IsApplicationAdministrator,
            gblCurrentUser.IsControllerOwnData
        )
    },
    {
        ItemKey: "lang",
        ItemDisplayName: $"{gblCurrentUser.Mail}",
        ItemIconName: "Mail",
        ItemVisible: Not(IsBlank(gblCurrentUser.Mail))
    },
    {
        ItemKey: "lang",
        ItemDisplayName: $"{gblCurrentUser.Language}, [{gblCurrentUser.Lang}]",
        ItemIconName: "LocaleLanguage"
    },
    {
        ItemKey: "countries",
        ItemDisplayName: $"{gblCurrentUser.CompanyName}",
        ItemIconName: "Home"
    },
    {
        ItemKey: "company",
        ItemDisplayName: If(
            Not(IsBlankOrError(gblCurrentUser.EditableCounties)),
            $"{Concat(
                gblCurrentUser.EditableCounties,
                $"{name}; "
            )}",
            Blank()
        ),
        ItemIconName: "AddHome"
    },
    {
        ItemKey: "version",
        ItemDisplayName: $"version {gblAppVersion} ({gblEnvironmentName})",
        ItemIconName: "Info"
    }
)
